// CPU-bound: параллельная сумма на нескольких потоках
long[] data = ...;
int n = Runtime.getRuntime().availableProcessors();
ExecutorService pool = Executors.newFixedThreadPool(n);
AtomicLong sum = new AtomicLong();
int chunk = data.length / n;
List<Future<?>> futs = new ArrayList<>();
for (int i = 0; i < n; i++) {
  final int from = i * chunk, to = (i == n-1) ? data.length : from + chunk;
  futs.add(pool.submit(() -> {
    long local = 0;
    for (int j = from; j < to; j++) local += data[j];
    sum.addAndGet(local); // атомик — безопасная синхронизация
  }));
}
for (Future<?> f : futs) f.get();
pool.shutdown();
```

