```js
// функция
function discount(price, pct) {
  if (pct < 0 || pct > 100) throw new RangeError('bad pct');
  return price - price * pct / 100;
}
// юнит-тесты
it('applies discount', () => expect(discount(100, 10)).toBe(90));
it('rejects negative pct', () => expect(() => discount(100, -1)).toThrow(RangeError));
it('handles zero pct', () => expect(discount(100, 0)).toBe(100));
```

